CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(160) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, phone VARCHAR(40), profile_photo MEDIUMBLOB NULL, profile_photo_mime ENUM('image/jpeg','image/png','image/webp') NULL, status ENUM('active','suspended','pending') NOT NULL DEFAULT 'active', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS roles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, description VARCHAR(255), is_admin BOOLEAN NOT NULL DEFAULT FALSE, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS permissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, permission_key VARCHAR(120) NOT NULL UNIQUE, description VARCHAR(255)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS user_roles (user_id BIGINT UNSIGNED NOT NULL, role_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS role_permissions (role_id BIGINT UNSIGNED NOT NULL, permission_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE, FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS admin_sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, token_hash CHAR(64) NOT NULL UNIQUE, user_id BIGINT UNSIGNED NOT NULL, expires_at DATETIME NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX(expires_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS user_sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, token_hash CHAR(64) NOT NULL UNIQUE, user_id BIGINT UNSIGNED NOT NULL, expires_at DATETIME NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX(expires_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS password_reset_tokens (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, used_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_password_reset_user (user_id), INDEX idx_password_reset_expiry (expires_at), CONSTRAINT fk_password_reset_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS service_categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, description VARCHAR(500), display_order INT UNSIGNED NOT NULL DEFAULT 0, image MEDIUMBLOB NULL, image_mime ENUM('image/jpeg','image/png','image/webp') NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS vendor_profiles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, business_name VARCHAR(160) NOT NULL, category_id BIGINT UNSIGNED, city VARCHAR(120), description TEXT, verification_status ENUM('pending','verified','rejected') NOT NULL DEFAULT 'pending', verification_reason VARCHAR(500), verified_at DATETIME, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY(user_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(category_id) REFERENCES service_categories(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS services (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, vendor_id BIGINT UNSIGNED NOT NULL, category_id BIGINT UNSIGNED, title VARCHAR(180) NOT NULL, description TEXT, price DECIMAL(12,2), currency CHAR(3) NOT NULL DEFAULT 'ETB', status ENUM('draft','active','archived') NOT NULL DEFAULT 'active', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(vendor_id) REFERENCES vendor_profiles(id), FOREIGN KEY(category_id) REFERENCES service_categories(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organizer_id BIGINT UNSIGNED NOT NULL, title VARCHAR(180) NOT NULL, event_type VARCHAR(80) NOT NULL, city VARCHAR(120), start_date DATETIME NOT NULL, end_date DATETIME, budget DECIMAL(12,2), status ENUM('draft','active','booked','in_progress','completed','cancelled') NOT NULL DEFAULT 'draft', notes TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(organizer_id) REFERENCES users(id), INDEX(status,start_date)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS bookings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, event_id BIGINT UNSIGNED NOT NULL, vendor_id BIGINT UNSIGNED NOT NULL, service_id BIGINT UNSIGNED NULL, scheduled_date DATETIME NULL, service_description VARCHAR(255) NOT NULL, quoted_amount DECIMAL(12,2) NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'USD', status ENUM('requested','quoted','accepted','rejected','cancelled','completed','under_review') NOT NULL DEFAULT 'requested', moderation_reason VARCHAR(500), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(event_id) REFERENCES events(id), FOREIGN KEY(vendor_id) REFERENCES vendor_profiles(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS booking_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, booking_id BIGINT UNSIGNED NOT NULL, actor_id BIGINT UNSIGNED NULL, action VARCHAR(80) NOT NULL, from_status VARCHAR(40), to_status VARCHAR(40), reason VARCHAR(500), details JSON NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE RESTRICT, FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE SET NULL, INDEX idx_booking_history_booking_created (booking_id, created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, booking_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(12,2) NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'USD', provider VARCHAR(40), payment_method VARCHAR(80), provider_reference VARCHAR(190), idempotency_key VARCHAR(120), status ENUM('pending','authorized','paid','failed','cancelled','refunded','partially_refunded','refund_pending') NOT NULL DEFAULT 'pending', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, verified_at DATETIME NULL, UNIQUE KEY uq_payments_idempotency_key (idempotency_key), UNIQUE KEY uq_payments_provider_reference (provider, provider_reference), FOREIGN KEY(booking_id) REFERENCES bookings(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reviews (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, booking_id BIGINT UNSIGNED NOT NULL, rating TINYINT UNSIGNED NOT NULL, comment TEXT, status ENUM('published','hidden','flagged') NOT NULL DEFAULT 'published', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE RESTRICT, CHECK (rating BETWEEN 1 AND 5)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS review_history (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, review_id BIGINT UNSIGNED NOT NULL, actor_id BIGINT UNSIGNED NULL, action VARCHAR(80) NOT NULL, from_status VARCHAR(40) NULL, to_status VARCHAR(40) NULL, reason VARCHAR(500) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(review_id) REFERENCES reviews(id) ON DELETE RESTRICT, FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE SET NULL, INDEX idx_review_history_review_created (review_id, created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS complaints (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, booking_id BIGINT UNSIGNED, subject VARCHAR(180) NOT NULL, details TEXT NOT NULL, status ENUM('open','under_review','resolved','closed') NOT NULL DEFAULT 'open', resolution VARCHAR(1000), assigned_to BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT, FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE RESTRICT, FOREIGN KEY(assigned_to) REFERENCES users(id) ON DELETE SET NULL, INDEX idx_complaint_status (status), INDEX idx_complaints_assigned_status (assigned_to, status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS complaint_history (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, complaint_id BIGINT UNSIGNED NOT NULL, actor_id BIGINT UNSIGNED NULL, action VARCHAR(80) NOT NULL, from_status VARCHAR(40) NULL, to_status VARCHAR(40) NULL, reason VARCHAR(500) NULL, details JSON NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(complaint_id) REFERENCES complaints(id) ON DELETE RESTRICT, FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE SET NULL, INDEX idx_complaint_history_complaint_created (complaint_id, created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS complaint_attachments (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, complaint_id BIGINT UNSIGNED NOT NULL, uploaded_by BIGINT UNSIGNED NOT NULL, original_name VARCHAR(180) NOT NULL, content_type VARCHAR(80) NOT NULL, file_size INT UNSIGNED NOT NULL, sha256 CHAR(64) NOT NULL, file_data LONGBLOB NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(complaint_id) REFERENCES complaints(id) ON DELETE RESTRICT, FOREIGN KEY(uploaded_by) REFERENCES users(id) ON DELETE RESTRICT, INDEX idx_complaint_attachment_complaint (complaint_id, created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED, title VARCHAR(180) NOT NULL, message TEXT NOT NULL, notification_type VARCHAR(60) NOT NULL DEFAULT 'system', related_entity_type VARCHAR(60), related_entity_id VARCHAR(80), idempotency_key VARCHAR(190), status ENUM('queued','sent','failed','read') NOT NULL DEFAULT 'queued', read_at DATETIME NULL, delivery_channel ENUM('in_app','email') NOT NULL DEFAULT 'in_app', delivery_status ENUM('delivered','pending','failed','not_configured') NOT NULL DEFAULT 'delivered', delivery_attempts INT UNSIGNED NOT NULL DEFAULT 0, last_delivery_error VARCHAR(500), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_notifications_idempotency_key (idempotency_key), INDEX idx_notifications_recipient_created (user_id, created_at, id), INDEX idx_notifications_recipient_unread (user_id, status, created_at), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notification_history (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, notification_id BIGINT UNSIGNED NOT NULL, actor_id BIGINT UNSIGNED NULL, action VARCHAR(60) NOT NULL, details JSON NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(notification_id) REFERENCES notifications(id) ON DELETE RESTRICT, FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE SET NULL, INDEX idx_notification_history_notification_created (notification_id, created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS system_settings (setting_key VARCHAR(120) PRIMARY KEY, setting_value TEXT NOT NULL, updated_by BIGINT UNSIGNED NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT UNSIGNED NOT NULL, action VARCHAR(120) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id VARCHAR(80), details JSON NOT NULL, ip_address VARCHAR(45), request_id CHAR(36), outcome ENUM('success','failure') NOT NULL DEFAULT 'success', severity ENUM('info','warning','critical') NOT NULL DEFAULT 'info', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(actor_id) REFERENCES users(id), INDEX(created_at), INDEX idx_audit_request (request_id), INDEX idx_audit_action_date (action,created_at), INDEX idx_audit_severity_date (severity,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS module_locks (module_key VARCHAR(120) PRIMARY KEY, is_locked BOOLEAN NOT NULL DEFAULT FALSE, updated_by BIGINT UNSIGNED NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS site_content (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, page_key VARCHAR(80) NOT NULL, page_title VARCHAR(160) NOT NULL DEFAULT 'About EventHub', content JSON, is_published BOOLEAN NOT NULL DEFAULT TRUE, language VARCHAR(10) NOT NULL DEFAULT 'en', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY(page_key,language)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS contact_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED, full_name VARCHAR(160) NOT NULL, email VARCHAR(254) NOT NULL, phone VARCHAR(40), subject VARCHAR(200) NOT NULL, inquiry_type ENUM('general_inquiry','event_booking_support','vendor_support','service_request','payment_billing','technical_support','account_assistance','partnership_inquiry','feedback','other') NOT NULL DEFAULT 'general_inquiry', message TEXT NOT NULL, status ENUM('new','reviewed','in_progress','replied','resolved','closed') NOT NULL DEFAULT 'new', admin_reply TEXT, reviewed_by BIGINT UNSIGNED, reviewed_at DATETIME, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS event_package_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, event_id BIGINT UNSIGNED NULL, event_title VARCHAR(180) NOT NULL, event_type VARCHAR(80), requested_date DATETIME, requested_location VARCHAR(120), requester_name VARCHAR(160) NOT NULL, requester_email VARCHAR(254) NOT NULL, service_category VARCHAR(120), guest_count INT UNSIGNED, budget DECIMAL(12,2), notes TEXT, status ENUM('new','reviewed','replied','closed') NOT NULL DEFAULT 'new', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS refund_requests (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, payment_id BIGINT UNSIGNED NOT NULL, requester_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(12,2) NOT NULL, currency CHAR(3) NOT NULL, reason VARCHAR(500) NOT NULL, status ENUM('pending','processing','succeeded','failed','rejected') NOT NULL DEFAULT 'pending', idempotency_key VARCHAR(120) NOT NULL, decided_by BIGINT UNSIGNED NULL, decision_reason VARCHAR(500) NULL, provider_refund_reference VARCHAR(190) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, decided_at DATETIME NULL, processed_at DATETIME NULL, UNIQUE KEY uq_refund_idempotency_key (idempotency_key), INDEX idx_refund_status_created (status, created_at), INDEX idx_refund_payment_status (payment_id, status), FOREIGN KEY(payment_id) REFERENCES payments(id) ON DELETE RESTRICT, FOREIGN KEY(requester_id) REFERENCES users(id) ON DELETE RESTRICT, FOREIGN KEY(decided_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payment_history (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, payment_id BIGINT UNSIGNED NOT NULL, refund_id BIGINT UNSIGNED NULL, actor_id BIGINT UNSIGNED NULL, action VARCHAR(80) NOT NULL, from_status VARCHAR(40) NULL, to_status VARCHAR(40) NULL, details JSON NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_payment_history_payment_created (payment_id, created_at), INDEX idx_payment_history_refund_created (refund_id, created_at), FOREIGN KEY(payment_id) REFERENCES payments(id) ON DELETE RESTRICT, FOREIGN KEY(refund_id) REFERENCES refund_requests(id) ON DELETE RESTRICT, FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payment_provider_events (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, provider VARCHAR(40) NOT NULL, event_id VARCHAR(190) NOT NULL, event_type VARCHAR(80) NOT NULL, received_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_provider_event (provider, event_id)) ENGINE=InnoDB;
